// Unsharp-mask filter family executor: nppiFilterUnsharpBorder* and
// nppiFilterUnsharpGetBufferSize*.
//
// Host-visible surface (safe for plain .cpp translation units): the entry
// points are declared here and defined + explicitly instantiated in
// nppi_filter_unsharp_executor.cu.  The public wrappers are generated by
// mpp_scripts/gen_family.py (mpp_scripts/families/nppi_filter_unsharp_*.json).
//
// Semantics (baseline NVIDIA NPP 13.4 on RTX 5090, probe-verified; the probes
// and their raw dumps live in probe_f11/, see probe_j/l/m/n/o/p):
//   * Kernel: normalised 2-D Gaussian, tap(a,b) = exp(-d2/(2*sigma^2)) / sum,
//     with the window k x k, k = 2*ceil(radius)+1 when radius > 0.  With
//     radius == 0 the radius is chosen from sigma and the destination dtype
//     (wider dtypes keep a wider window): 8u/16u/16s/32f sigma=1 -> k=7/9/9/15.
//   * The taps are written to pDeviceBuffer (k*k*4 bytes, the exact size
//     nppiFilterUnsharpGetBufferSize reports; a buffer of any other size makes
//     the transfer fail and the call returns NPP_CUDA_KERNEL_EXECUTION_ERROR).
//   * Result: dst = src + weight * (src - blurred), evaluated in floating
//     point.  Integer destinations saturate (8u [0,255], 16u [0,65535],
//     16s [-32768,32767]) after C truncation toward zero; 32f stores the
//     float result unchanged.
//   * nThreshold > 0 suppresses the sharpening of low-contrast pixels: the
//     source value is copied when |src - blurred| <= nThreshold * kScale with
//     kScale = 128 / 32768 / 16384 / 2^32 for 8u / 16u / 16s / 32f (the
//     threshold is compared in a fixed-point domain, probe-verified).
//   * Only NPP_BORDER_REPLICATE is supported.  Source reads are clamped to
//     [pSrc - oSrcOffset, pSrc - oSrcOffset + ROI - 1] per axis, i.e. the
//     image is assumed to be exactly the size of the ROI and to start
//     oSrcOffset pixels before pSrc.  The centre sample used in the formula is
//     clamped the same way (probe-verified with impulse responses).
//   * AC4 (AlphaPreserve) computes channels 0..2 and leaves dst alpha alone;
//     C4 computes all four channels.  Channel planes are independent.
//   * Validation order (probe-verified): null src/dst/buffer ->
//     negative ROI (NPP_SIZE_ERROR) -> unsupported border type
//     (NPP_NOT_SUPPORTED_MODE_ERROR) -> radius < 0 or sigma <= 0
//     (NPP_SIZE_ERROR) -> kernel larger than the ROI, which also covers a zero
//     ROI (NPP_SIZE_ERROR) -> dst step (NPP_STEP_ERROR / NPP_NOT_EVEN_STEP_ERROR).
//     The source step and oSrcOffset are never validated.
//   * GetBufferSize reports k*k*sizeof(Npp32f) bytes for every dtype and
//     channel count and validates radius/sigma: a negative radius or a negative
//     sigma is NPP_SIZE_ERROR, sigma == 0 is accepted when the radius is
//     explicit (the filter itself needs sigma > 0), and an auto radius with
//     sigma <= 0 is NPP_SIZE_ERROR (NPP 13.4 hangs on sigma == 0 there).
#ifndef NPPI_FILTER_UNSHARP_EXECUTOR_H
#define NPPI_FILTER_UNSHARP_EXECUTOR_H

#include "npp.h"

namespace nppi {
namespace filter {

// Destination element traits used to pick the auto-radius rule and the
// threshold scale.
enum UnsharpDtype {
  kUnsharpU8,
  kUnsharpU16,
  kUnsharpS16,
  kUnsharpF32,
};

// Kernel width (k x k) and scratch size in bytes for a radius/sigma pair.
int unsharpKernelSize(float radius, float sigma, UnsharpDtype dtype);
int unsharpBufferSize(float radius, float sigma, UnsharpDtype dtype);

// nppiFilterUnsharpGetBufferSize* body (dtype selects the auto-radius rule).
NppStatus unsharpGetBufferSize(float radius, float sigma, UnsharpDtype dtype, int *hpBufferSize);

// Same, with the destination type selecting the rule (generated wrappers).
template <typename Src>
NppStatus unsharpGetBufferSizeT(float radius, float sigma, int *hpBufferSize);

// nppiFilterUnsharpBorder* body.  Src/Dst are the same type in every variant.
template <typename Src, typename Dst, int Channels, bool AlphaPreserve>
NppStatus filterUnsharpBorder(const Src *pSrc, int nSrcStep, NppiPoint oSrcOffset, Dst *pDst, int nDstStep,
                              NppiSize oSizeROI, float nRadius, float nSigma, float nWeight, float nThreshold,
                              NppiBorderType eBorderType, Npp8u *pDeviceBuffer, cudaStream_t stream);

}  // namespace filter
}  // namespace nppi

#endif  // NPPI_FILTER_UNSHARP_EXECUTOR_H
